css:
.trustsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e7ecf4;
    background: linear-gradient(165deg, #0a1428 0%, #0f1d39 55%, #122544 100%);
    border-radius: 18px;
}

.trustsim-container * {
    box-sizing: border-box;
}

.trustsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0c1b34 0%, #14305b 55%, #1b3f73 100%);
    color: #f3f7fc;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #1f3c6b;
    box-shadow: 0 12px 34px rgba(2, 8, 20, 0.55);
}

.trustsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #f6d98a;
}

.trustsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f0c869;
    background: rgba(246, 200, 105, 0.12);
    border: 1px solid rgba(246, 200, 105, 0.28);
    padding: 5px 14px;
    border-radius: 999px;
}

.trustsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c6d3e6;
}

.trustsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #b9c8e0;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.trustsim-period-counter #currentDay,
.trustsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #f6d98a;
}

.trustsim-round-name {
    background: rgba(246, 200, 105, 0.14);
    color: #f6d98a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid rgba(246, 200, 105, 0.30);
}

.trustsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ffb4a2;
    background: rgba(201, 74, 53, 0.18);
    padding: 4px 12px;
    border-radius: 999px;
    border: 1px solid rgba(201, 74, 53, 0.35);
}

.trustsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.trustsim-status-card {
    background: #0e1f3c;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #1d3962;
    box-shadow: 0 6px 18px rgba(2, 8, 20, 0.40);
    border-top: 4px solid #2f6fb0;
}

.trustsim-card-trust { border-top-color: #f0c869; }
.trustsim-card-contain { border-top-color: #3fb98a; }
.trustsim-card-exploit { border-top-color: #c94a35; }
.trustsim-card-segment { border-top-color: #8a6fd6; }

.trustsim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8aa0c2;
}

.trustsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f3f7fc;
}

.trustsim-card-trust .trustsim-value { color: #f6d98a; }
.trustsim-card-contain .trustsim-value { color: #5fd6a6; }
.trustsim-card-exploit .trustsim-value { color: #ff8f7c; }
.trustsim-card-segment .trustsim-value { color: #b29bea; }

.trustsim-sublabel {
    font-size: 0.74rem;
    color: #7e93b6;
    line-height: 1.35;
}

.trustsim-trust-below .trustsim-value { color: #ff6f59; }
.trustsim-trust-safe .trustsim-value { color: #5fd6a6; }

.trustsim-contain-target .trustsim-value { color: #5fd6a6; }
.trustsim-contain-low .trustsim-value { color: #ff8f7c; }

.trustsim-exploit-high .trustsim-value { color: #ff6f59; }

.trustsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
    background: #081429;
    color: #e7ecf4;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border: 1px solid #1d3962;
}

.trustsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f6d98a;
}

.trustsim-savings {
    font-size: 0.92rem;
    color: #5fd6a6;
    font-weight: 800;
}

.trustsim-budget-over #budgetDisplay {
    color: #ff6f59;
}

.trustsim-briefing {
    display: flex;
    gap: 14px;
    background: #0e1f3c;
    border-left: 5px solid #f0c869;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    border: 1px solid #1d3962;
    box-shadow: 0 6px 18px rgba(2, 8, 20, 0.35);
}

.trustsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.trustsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #f6d98a;
    margin-bottom: 6px;
}

.trustsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #cdd9ec;
}

.trustsim-briefing-text strong { color: #5fd6a6; }
.trustsim-briefing-text em { color: #ffb4a2; font-style: italic; }

.trustsim-controls {
    background: #0e1f3c;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #1d3962;
    box-shadow: 0 6px 18px rgba(2, 8, 20, 0.40);
}

.trustsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #f3f7fc;
    border-bottom: 2px solid #1d3962;
    padding-bottom: 8px;
}

.trustsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #cdd9ec;
    margin: 14px 0 6px;
}

.trustsim-container select,
.trustsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2a4a78;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0a1a33;
    color: #eef3fb;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.trustsim-container select:focus,
.trustsim-container input[type="number"]:focus {
    outline: none;
    border-color: #f0c869;
    box-shadow: 0 0 0 3px rgba(240, 200, 105, 0.18);
}

.trustsim-container select option {
    background-color: #0a1a33;
    color: #eef3fb;
}

.trustsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #f0c869;
}

.trustsim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb3d4;
    margin-top: 4px;
}

.trustsim-range-readout span:nth-child(2) {
    color: #f6d98a;
    font-weight: 800;
}

.trustsim-hint {
    font-size: 0.8rem;
    color: #7e93b6;
    margin-top: 4px;
    line-height: 1.4;
}

.trustsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.trustsim-container .btn-primary {
    background: linear-gradient(135deg, #c79b34 0%, #f0c869 100%);
    border: none;
    color: #20160a;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(199, 155, 52, 0.32);
}

.trustsim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.trustsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #2a4a78;
    color: #9fb3d4;
    background: transparent;
}

.trustsim-container .btn-outline-secondary:hover {
    background: rgba(42, 74, 120, 0.35);
    color: #eef3fb;
}

.trustsim-coach {
    background: linear-gradient(135deg, #081429 0%, #0d203e 100%);
    color: #d8e2f2;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border: 1px solid #25457a;
    box-shadow: 0 8px 22px rgba(2, 8, 20, 0.45);
}

.trustsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0c869;
    margin-bottom: 8px;
}

.trustsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.trustsim-coach-body strong { color: #f6d98a; }
.trustsim-coach-body em { color: #ffb4a2; font-style: italic; }

.trustsim-history,
.trustsim-chart {
    background: #0e1f3c;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #1d3962;
    box-shadow: 0 6px 18px rgba(2, 8, 20, 0.40);
}

.trustsim-history h3,
.trustsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #f3f7fc;
}

.trustsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #cdd9ec;
}

.trustsim-container table#usfHistoryTable th {
    background: #0a1a33;
    color: #f6d98a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #25457a;
}

.trustsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #1a3258;
}

.trustsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #0c1c38;
}

.trustsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .trustsim-container {
        padding: 14px;
    }
    .trustsim-header h1 {
        font-size: 1.7rem;
    }
    .trustsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .trustsim-value {
        font-size: 2rem;
    }
    .trustsim-clock {
        margin-left: 0;
    }
    .trustsim-period-counter {
        font-size: 0.88rem;
    }
    .trustsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .trustsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light modal, trustsim) ---- */
.trustsim-completion { padding: 8px 4px 4px; }
.trustsim-cm-head { text-align: center; margin-bottom: 16px; }
.trustsim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #2f6f6a; }
.trustsim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #6a9b96; }
.trustsim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #14213d; }
.trustsim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.trustsim-cm-yes { background: rgba(47,111,106,0.14); color: #256b64; border: 1px solid rgba(47,111,106,0.5); }
.trustsim-cm-no { background: rgba(199,154,60,0.16); color: #8a6a1f; border: 1px solid rgba(199,154,60,0.5); }
.trustsim-cm-fail { background: rgba(192,57,43,0.12); color: #b0392b; border: 1px solid rgba(192,57,43,0.45); }
.trustsim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.trustsim-cm-metric { flex: 1 1 110px; min-width: 100px; background: rgba(20,33,61,0.06); border: 1px solid rgba(20,33,61,0.16); border-radius: 10px; padding: 10px 8px; text-align: center; }
.trustsim-cm-metric-risk { background: rgba(192,57,43,0.06); border-color: rgba(192,57,43,0.20); }
.trustsim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #23304f; }
.trustsim-cm-metric-risk .trustsim-cm-mv { color: #b0392b; }
.trustsim-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5a6577; text-transform: uppercase; letter-spacing: 0.03em; }
.trustsim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #14213d; }
.trustsim-cm-insights { margin: 0; padding-left: 20px; }
.trustsim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #2b3547; }

