                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Demir Bank A.Ş. / TRY).
            this.START_TRUST = 74;          // published Brand Trust Index
            this.SECTOR_MEDIAN = 61;        // peer-set median
            this.TRUST_FLOOR = 70;          // recovery floor
            this.NAIVE_TRUST = 65;          // naïve design (−9 pts)
            this.START_EXPLOIT = 30;        // perceived audience-size + exploitation; headroom up and down
            this.CONTAIN_TARGET = 55;       // Finance's savings assumption (%)
            this.CONTAIN_OK = 52;           // operational on-target band (segmentation trades a slice)
            this.SAVINGS_AT_TARGET = 310;   // ₺310M at 55% containment
            this.SAVINGS_PER_10 = 56;       // ≈ ₺56M per 10 containment points
            this.BUDGET_CAP = 4.0;          // ₺4.0M build budget (millions)
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    trust: this.START_TRUST,
                    contain: 0,
                    exploit: this.START_EXPLOIT,
                    segment: this.START_TRUST,
                    naiveTrust: this.NAIVE_TRUST,
                    budgetUsed: 0,
                    savings: 0,
                    kvkkBreach: false,
                    covertFlag: false,
                    incidentHit: false,
                    trustHistory: [this.START_TRUST],
                    containHistory: [0],
                    exploitHistory: [this.START_EXPLOIT],
                    segmentHistory: [this.START_TRUST],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIXED/weak play — never the textbook-correct set.
                state.decisions = {
                    mechanism: `creepy`,
                    segment: `all`,
                    contacts: `balance`,
                    rigour: 55,
                    disclosure: `footnote`,
                    confidentiality: `none`,
                    persona: `neutral`,
                    data: `standard`,
                    fallback: `single`,
                    visibility: `onrequest`,
                    incident: `quiet`,
                    containment: 55,
                    pitch: `savings`,
                    monitoring: `trust`,
                    journalist: `nocomment`,
                    recovery: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const me = document.getElementById(`mechanismInput`);
                const sg = document.getElementById(`segmentInput`);
                const co = document.getElementById(`contactsInput`);
                const ri = document.getElementById(`rigourInput`);
                if (me) decisions.mechanism = me.value;
                if (sg) decisions.segment = sg.value;
                if (co) decisions.contacts = co.value;
                if (ri) decisions.rigour = parseInt(ri.value, 10);
                if (!Number.isFinite(decisions.rigour) || decisions.rigour < 0 || decisions.rigour > 100) {
                    warn(`warn_rigour_range`); return false;
                }
            } else if (round === 2) {
                const di = document.getElementById(`disclosureInput`);
                const cf = document.getElementById(`confidentialityInput`);
                const pe = document.getElementById(`personaInput`);
                const da = document.getElementById(`dataInput`);
                if (di) decisions.disclosure = di.value;
                if (cf) decisions.confidentiality = cf.value;
                if (pe) decisions.persona = pe.value;
                if (da) decisions.data = da.value;
                // Budget guard: the configured design must fit the fixed ₺4.0M build budget.
                const spend = this._round2Spend(decisions);
                if (spend > this.BUDGET_CAP + 0.0001) {
                    warn(`warn_budget`); return false;
                }
            } else if (round === 3) {
                const fb = document.getElementById(`fallbackInput`);
                const vi = document.getElementById(`visibilityInput`);
                const inc = document.getElementById(`incidentInput`);
                const ct = document.getElementById(`containmentInput`);
                if (fb) decisions.fallback = fb.value;
                if (vi) decisions.visibility = vi.value;
                if (inc) decisions.incident = inc.value;
                if (ct) decisions.containment = parseInt(ct.value, 10);
                if (!Number.isFinite(decisions.containment) || decisions.containment < 0 || decisions.containment > 80) {
                    warn(`warn_containment_range`); return false;
                }
            } else if (round === 4) {
                const pi = document.getElementById(`pitchInput`);
                const mo = document.getElementById(`monitoringInput`);
                const jr = document.getElementById(`journalistInput`);
                const re = document.getElementById(`recoveryInput`);
                if (pi) decisions.pitch = pi.value;
                if (mo) decisions.monitoring = mo.value;
                if (jr) decisions.journalist = jr.value;
                if (re) decisions.recovery = parseInt(re.value, 10);
                if (!Number.isFinite(decisions.recovery) || decisions.recovery < 0 || decisions.recovery > 100) {
                    warn(`warn_recovery_range`); return false;
                }
            }
            return true;
        }

        _round2Spend(d) {
            let s = 0;
            s += ({ clear: 0.4, footnote: 0.1, covert: 0.0 })[d.disclosure] || 0;
            s += ({ genuine: 1.2, none: 0.0, empty: 0.3 })[d.confidentiality] || 0;
            s += ({ warm: 0.6, neutral: 0.2, fake: 0.5 })[d.persona] || 0;
            s += ({ minimised: 1.4, standard: 0.6, full: 0.3 })[d.data] || 0;
            return Math.round(s * 100) / 100;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // trustDelta = move in headline Brand Trust Index (small, realistic moves with headroom)
            // exploitDelta = move in perceived audience-size/exploitation (lower is better)
            // containDelta = move in AI-containment %
            // segWeight = how strongly the privacy-concerned segment amplifies a trust move (≈ double)
            let trustDelta = 0, exploitDelta = 0, containDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;
            // Privacy-concerned segment amplifies trust moves and is dragged hard by exploitation.
            const segWeight = 0.85;

            if (round === 1) {
                // Diagnose the mechanism — audience-size inference + exploitation, NOT generic AI dislike.
                if (d.mechanism === `audience`) {
                    trustDelta += 1; exploitDelta -= 2; coachKey = `coach_r1_mech_right`;
                } else if (d.mechanism === `creepy`) {
                    trustDelta -= 2; exploitDelta += 2; coachKey = `coach_r1_creepy`;
                } else if (d.mechanism === `accuracy`) {
                    trustDelta -= 2; exploitDelta += 1; coachKey = `coach_r1_accuracy`;
                } else {
                    trustDelta -= 3; exploitDelta += 2; coachKey = `coach_r1_novelty`;
                }

                // Most-exposed segment: the privacy-concerned 38% holding 56% of deposits.
                if (d.segment === `privacy`) {
                    trustDelta += 1;
                    if (d.mechanism === `audience`) coachKey = `coach_r1_diag_sharp`;
                } else if (d.segment === `all`) {
                    trustDelta -= 2; coachKey = `coach_r1_blended`;
                } else {
                    trustDelta -= 1;
                }

                // Highest-trust-cost contact types: emotional/high-stakes disclosures.
                if (d.contacts === `emotional`) { trustDelta += 1; }
                else if (d.contacts === `all`) { trustDelta -= 2; coachKey = `coach_r1_onesize`; }
                else { trustDelta -= 1; }

                // Diagnostic rigour: willingness to name the real mechanism vs a cosmetic fix.
                if (d.rigour >= 60) { trustDelta += 1; exploitDelta -= 1; }
                else if (d.rigour <= 25) { trustDelta -= 2; coachKey = `coach_r1_lowrigour`; }

                summaryKey = (d.mechanism === `audience` && d.segment === `privacy` && d.contacts === `emotional`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Configure the trust architecture across four costed levers.
                spend = this._round2Spend(d);

                // (a) Disclosure — covert reads as deception; clear labelling protects trust and KVKK posture.
                switch (d.disclosure) {
                    case `clear`: trustDelta += 1; exploitDelta -= 2; coachKey = `coach_r2_disc_clear`; break;
                    case `footnote`: trustDelta -= 1; exploitDelta += 2; break;
                    case `covert`: trustDelta -= 6; exploitDelta += 7; ds.covertFlag = true; coachKey = `coach_r2_covert`; break;
                }

                // (b) Confidentiality assurance — a kept promise shrinks the perceived audience (the core mechanism).
                switch (d.confidentiality) {
                    case `genuine`: trustDelta += 1; exploitDelta -= 4; coachKey = (d.disclosure === `clear`) ? `coach_r2_conf_genuine` : coachKey; break;
                    case `none`: exploitDelta += 3; break;
                    case `empty`: trustDelta -= 5; exploitDelta += 5; ds.kvkkBreach = true; coachKey = `coach_r2_empty`; break;
                }

                // (c) Anthropomorphism — a warm, named persona helps; a fake human identity is deception.
                switch (d.persona) {
                    case `warm`: trustDelta += 1; exploitDelta -= 1; break;
                    case `neutral`: trustDelta += 0; exploitDelta += 1; break;
                    case `fake`: trustDelta -= 3; exploitDelta += 4; ds.covertFlag = true; coachKey = `coach_r2_fakepersona`; break;
                }

                // (d) Data-use scope — minimisation directly shrinks the audience inference; full ingestion inflates it.
                switch (d.data) {
                    case `minimised`: exploitDelta -= 4; coachKey = (d.confidentiality === `genuine` && coachKey === `coach_r2_conf_genuine`) ? `coach_r2_architecture` : coachKey; break;
                    case `standard`: trustDelta += 0; exploitDelta += 2; break;
                    case `full`: trustDelta -= 3; exploitDelta += 7; coachKey = `coach_r2_fulldata`; break;
                }

                // Cosmetic-fix trap (Common Error 2): warm persona but full data / no confidentiality.
                if (d.persona === `warm` && d.data === `full` && d.confidentiality !== `genuine`) {
                    coachKey = `coach_r2_cosmetic`;
                }

                const cleanArchitecture = (d.disclosure === `clear` && d.confidentiality === `genuine` && d.data === `minimised`);
                summaryKey = cleanArchitecture ? `sum_r2_good` : ((ds.kvkkBreach || ds.covertFlag) ? `sum_r2_breach` : `sum_r2_weak`);
            } else if (round === 3) {
                // Human-fallback rule + the viral incident + containment ambition.
                ds.incidentHit = true;

                // Fallback segmentation: high-stakes emotional contacts must never start with AI.
                switch (d.fallback) {
                    case `segmented`: trustDelta += 2; exploitDelta -= 2; coachKey = `coach_r3_segmented`; break;
                    case `single`: trustDelta -= 2; exploitDelta += 3; coachKey = `coach_r3_single`; break;
                    case `aifirst`: trustDelta -= 5; exploitDelta += 5; coachKey = `coach_r3_aifirst`; break;
                }

                // Visibility of the human handoff.
                switch (d.visibility) {
                    case `prominent`: trustDelta += 1; exploitDelta -= 1; break;
                    case `onrequest`: trustDelta += 0; break;
                    case `hidden`: trustDelta -= 2; exploitDelta += 3; coachKey = `coach_r3_hidden`; break;
                }

                // Incident response: owning it recovers trust; denial deepens the crisis.
                spend += ({ own: 0.4, quiet: 0.1, deny: 0.0 })[d.incident] || 0;
                switch (d.incident) {
                    case `own`: trustDelta += 1; exploitDelta -= 2; coachKey = (d.fallback === `segmented`) ? `coach_r3_recover` : coachKey; break;
                    case `quiet`: trustDelta -= 1; exploitDelta += 1; break;
                    case `deny`: trustDelta -= 4; exploitDelta += 4; coachKey = `coach_r3_deny`; break;
                }

                // Containment ambition: raises the contain meter but, if fallback is unsafe, costs trust.
                let effectiveContain = d.containment;
                if (d.fallback === `aifirst` || d.fallback === `single`) {
                    // Pushing containment on an unsafe fallback hits trust harder the more you push.
                    trustDelta -= Math.round((d.containment - 40) / 15);
                }
                if (d.fallback === `segmented`) {
                    // Segmenting holds back a slice of contacts from AI — a small, fair containment cost.
                    effectiveContain = Math.max(0, d.containment - 6);
                }
                containDelta += effectiveContain;

                summaryKey = (d.fallback === `segmented` && d.incident === `own`) ? `sum_r3_good` : (d.fallback === `aifirst` ? `sum_r3_unsafe` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend the numbers + monitoring + the journalist + recovery commitment.
                switch (d.pitch) {
                    case `reconcile`: trustDelta += 1; coachKey = `coach_r4_reconcile`; break;
                    case `savings`: trustDelta -= 2; exploitDelta += 2; containDelta += 4; coachKey = `coach_r4_savings`; break;
                    case `trustonly`: containDelta -= 12; coachKey = `coach_r4_trustonly`; break;
                }

                switch (d.monitoring) {
                    case `full`: trustDelta += 1; exploitDelta -= 2; coachKey = (d.pitch === `reconcile`) ? `coach_r4_monitor` : coachKey; break;
                    case `trust`: exploitDelta += 1; break;
                    case `none`: trustDelta -= 2; exploitDelta += 3; coachKey = `coach_r4_nomonitor`; break;
                }

                switch (d.journalist) {
                    case `transparent`: trustDelta += 1; exploitDelta -= 2; break;
                    case `nocomment`: trustDelta -= 1; exploitDelta += 2; break;
                    case `spin`: trustDelta -= 3; exploitDelta += 4; coachKey = (ds.kvkkBreach) ? `coach_r4_spinbreach` : `coach_r4_spin`; break;
                }

                // Recovery-plan conviction nudges trust.
                trustDelta += Math.round((d.recovery - 55) / 25);

                summaryKey = (d.pitch === `reconcile` && d.monitoring === `full` && d.journalist === `transparent`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // A live KVKK breach (empty confidentiality promise) keeps bleeding trust every later round.
            if (ds.kvkkBreach && round >= 3) { trustDelta -= 2; exploitDelta += 2; }
            // A covert/deceptive identity keeps the journalist risk alive.
            if (ds.covertFlag && round === 4 && d.journalist !== `transparent`) { trustDelta -= 2; }

            // Resource & savings accounting.
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 100) / 100;

            // Apply meter moves with headroom; nothing pegs before the late rounds.
            ds.trust = Math.max(0, Math.min(100, ds.trust + trustDelta));
            ds.exploit = Math.max(0, Math.min(100, ds.exploit + exploitDelta));
            ds.contain = Math.max(0, Math.min(75, ds.contain + containDelta));

            // The privacy-concerned segment amplifies trust moves and is dragged hard by exploitation.
            const segDelta = trustDelta * segWeight - Math.max(0, exploitDelta) * 0.6;
            ds.segment = Math.max(0, Math.min(100, ds.segment + segDelta));

            // Annual savings track containment (linear ≈ ₺56M per 10 pts).
            ds.savings = Math.round(ds.contain * (this.SAVINGS_PER_10 / 10));

            ds.trustHistory.push(Math.round(ds.trust));
            ds.containHistory.push(Math.round(ds.contain));
            ds.exploitHistory.push(Math.round(ds.exploit));
            ds.segmentHistory.push(Math.round(ds.segment));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            // Composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                trust: Math.round(ds.trust),
                trustDelta: Math.round(trustDelta),
                contain: Math.round(ds.contain),
                containDelta: Math.round(containDelta),
                exploit: Math.round(ds.exploit),
                exploitDelta: Math.round(exploitDelta),
                segment: Math.round(ds.segment),
                savings: ds.savings,
                budgetUsed: ds.budgetUsed,
                kvkkBreach: ds.kvkkBreach,
                covertFlag: ds.covertFlag,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`trustDisplay`, `domainState.trust`, (v) => {
                const card = document.querySelector(`.trustsim-card-trust`);
                if (card) {
                    card.classList.toggle(`trustsim-trust-safe`, Number(v) >= this.TRUST_FLOOR);
                    card.classList.toggle(`trustsim-trust-below`, Number(v) < this.TRUST_FLOOR);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`containDisplay`, `domainState.contain`, (v) => {
                const card = document.querySelector(`.trustsim-card-contain`);
                if (card) {
                    card.classList.toggle(`trustsim-contain-target`, Number(v) >= this.CONTAIN_TARGET);
                    card.classList.toggle(`trustsim-contain-low`, Number(v) < this.CONTAIN_TARGET);
                }
                return Math.round(Number(v)) + `%`;
            });
            uiManager.bind(`exploitDisplay`, `domainState.exploit`, (v) => {
                const card = document.querySelector(`.trustsim-card-exploit`);
                if (card) card.classList.toggle(`trustsim-exploit-high`, Number(v) >= 45);
                return Math.round(Number(v));
            });
            uiManager.bind(`segmentDisplay`, `domainState.segment`, (v) => Math.round(Number(v)));
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.trustsim-budget-bar`);
                if (card) card.classList.toggle(`trustsim-budget-over`, Number(v) > this.BUDGET_CAP + 0.0001);
                return `₺` + Number(v).toFixed(1) + `M / ₺4.0M`;
            });
            uiManager.bind(`savingsDisplay`, `domainState.savings`, (v) => window.mySimulation.t(`savings_prefix`) + ` ₺` + Math.round(Number(v)) + `M / ₺310M`);

            const self = this;

            // Diagnostic-rigour slider readout.
            const ri = document.getElementById(`rigourInput`);
            const riReadout = document.getElementById(`rigourReadout`);
            if (ri && riReadout) {
                riReadout.textContent = ri.value;
                ri.addEventListener(`input`, function() { riReadout.textContent = ri.value; });
            }

            // Containment-ambition slider readout.
            const ct = document.getElementById(`containmentInput`);
            const ctReadout = document.getElementById(`containmentReadout`);
            if (ct && ctReadout) {
                ctReadout.textContent = ct.value;
                ct.addEventListener(`input`, function() { ctReadout.textContent = ct.value; });
            }

            // Round-2 live budget feedback on the budget bar.
            const r2Ids = [`disclosureInput`, `confidentialityInput`, `personaInput`, `dataInput`];
            const recompute = function() {
                const draft = {
                    disclosure: (document.getElementById(`disclosureInput`) || {}).value,
                    confidentiality: (document.getElementById(`confidentialityInput`) || {}).value,
                    persona: (document.getElementById(`personaInput`) || {}).value,
                    data: (document.getElementById(`dataInput`) || {}).value
                };
                const spend = self._round2Spend(draft);
                const bar = document.querySelector(`.trustsim-budget-bar`);
                if (bar) bar.classList.toggle(`trustsim-budget-over`, spend > self.BUDGET_CAP + 0.0001);
                const bd = document.getElementById(`budgetDisplay`);
                if (bd) bd.textContent = `₺` + spend.toFixed(1) + `M / ₺4.0M`;
            };
            r2Ids.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`change`, recompute);
            });
        }

        getChartConfig() {
            return {
                trustChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._cl(`legend_trust`, `Brand Trust Index`),
                                data: [],
                                borderColor: `#f0c869`,
                                backgroundColor: `rgba(240,200,105,0.14)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#f0c869`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_contain`, `AI-Containment %`),
                                data: [],
                                borderColor: `#3fb98a`,
                                backgroundColor: `rgba(63,185,138,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#3fb98a`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_exploit`, `Perceived Exploitation`),
                                data: [],
                                borderColor: `#c94a35`,
                                backgroundColor: `rgba(201,74,53,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#c94a35`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_segment`, `Privacy-Segment Trust`),
                                data: [],
                                borderColor: `#8a6fd6`,
                                backgroundColor: `rgba(138,111,214,0.08)`,
                                borderWidth: 2,
                                borderDash: [2, 3],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#8a6fd6`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#cdd9ec`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#8aa0c2` }, grid: { color: `rgba(140,160,200,0.12)` },
                                title: { display: true, text: this._cl(`axis_score`, `0–100`), color: `#8aa0c2` }
                            },
                            x: {
                                ticks: { color: `#8aa0c2` }, grid: { color: `rgba(140,160,200,0.08)` },
                                title: { display: true, text: this._cl(`axis_round`, `Round`), color: `#8aa0c2` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.trustHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                trustChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.trustHistory },
                        { data: ds.containHistory },
                        { data: ds.exploitHistory },
                        { data: ds.segmentHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const trust = Math.round(ds.trust);
            const contain = Math.round(ds.contain);
            const exploit = Math.round(ds.exploit);
            const segment = Math.round(ds.segment);
            const composite = Math.round(
                trust * 0.40 +
                Math.min(100, (contain / this.CONTAIN_TARGET) * 100) * 0.25 +
                (100 - exploit) * 0.20 +
                segment * 0.15
            );
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const metBadge = s.sound
                ? `<span class="trustsim-cm-badge trustsim-cm-yes">` + T(`cm_sound`) + `</span>`
                : `<span class="trustsim-cm-badge trustsim-cm-no">` + T(`cm_notsound`) + `</span>`;
            let failBadges = ``;
            if (s.kvkkBreach) failBadges += ` <span class="trustsim-cm-badge trustsim-cm-fail">` + T(`cm_kvkk`) + `</span>`;
            if (s.covertFlag) failBadges += ` <span class="trustsim-cm-badge trustsim-cm-fail">` + T(`cm_covert`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="trustsim-cm-metric"><span class="trustsim-cm-mv">` + Math.round(s.trust || 0) + `</span><span class="trustsim-cm-ml">` + T(`cm_m_trust`) + `</span></div>`
                + `<div class="trustsim-cm-metric"><span class="trustsim-cm-mv">` + Math.round(s.contain || 0) + `</span><span class="trustsim-cm-ml">` + T(`cm_m_contain`) + `</span></div>`
                + `<div class="trustsim-cm-metric trustsim-cm-metric-risk"><span class="trustsim-cm-mv">` + Math.round(s.exploit || 0) + `</span><span class="trustsim-cm-ml">` + T(`cm_m_exploit`) + `</span></div>`
                + `<div class="trustsim-cm-metric"><span class="trustsim-cm-mv">` + Math.round(s.segment || 0) + `</span><span class="trustsim-cm-ml">` + T(`cm_m_segment`) + `</span></div>`;
            return ``
                + `<div class="trustsim-completion">`
                +   `<div class="trustsim-cm-head">`
                +     `<div class="trustsim-cm-score">` + score + `<span class="trustsim-cm-score-max">/100</span></div>`
                +     `<div class="trustsim-cm-grade">` + grade + ` ` + metBadge + failBadges + `</div>`
                +   `</div>`
                +   `<div class="trustsim-cm-metrics">` + metrics + `</div>`
                +   `<div class="trustsim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="trustsim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const trust = Math.round(ds.trust);
            const contain = Math.round(ds.contain);
            const exploit = Math.round(ds.exploit);
            const segment = Math.round(ds.segment);
            const savings = ds.savings;

            const trustOk = trust >= this.TRUST_FLOOR;
            // A segmented, trust-safe design deliberately trades a slice of containment, landing
            // just under the headline 55% target — treat reaching the operational band as "on target".
            const containOk = contain >= this.CONTAIN_OK;
            const exploitOk = exploit <= 30;

            // Composite: trust 40%, containment 25%, low exploitation 20%, segment trust 15%. Single source: _composite(ds).
            const composite = this._composite(ds);

            let performanceKey = `grade_spent`;
            if (trustOk && containOk && exploitOk && composite >= 78) performanceKey = `grade_bydesign`;
            else if (trustOk && containOk) performanceKey = `grade_balanced`;
            else if (containOk && !trustOk) performanceKey = (ds.covertFlag ? `grade_covert` : `grade_sacrificed`);
            else if (trustOk && !containOk) performanceKey = `grade_overcorrected`;
            else if (trust >= this.SECTOR_MEDIAN) performanceKey = `grade_eroded`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (trustOk && containOk && exploitOk) insights.push(window.mySimulation.t(`insight_balanced`));
            else if (containOk && !trustOk) insights.push(window.mySimulation.t(`insight_covert`));
            else if (trustOk && !containOk) insights.push(window.mySimulation.t(`insight_overcorrect`));
            else insights.push(window.mySimulation.t(`insight_eroded`));

            if (ds.kvkkBreach) insights.push(window.mySimulation.t(`insight_kvkk`));
            if (ds.covertFlag) insights.push(window.mySimulation.t(`insight_covertflag`));
            if (exploit >= 45) insights.push(window.mySimulation.t(`insight_exploit`));
            if (segment < this.TRUST_FLOOR && trust >= this.TRUST_FLOOR) insights.push(window.mySimulation.t(`insight_segmentgap`));
            if (!containOk) insights.push(window.mySimulation.t(`insight_savingsshort`));
            if (trustOk && containOk && exploitOk && segment >= this.TRUST_FLOOR) insights.push(window.mySimulation.t(`insight_premium`));

            return {
                trust: trust,
                contain: contain,
                exploit: exploit,
                segment: segment,
                savings: savings,
                trustOk: trustOk,
                containOk: containOk,
                sound: trustOk && containOk && exploitOk,
                kvkkBreach: ds.kvkkBreach,
                covertFlag: ds.covertFlag,
                composite: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.kvkkBreach) return window.mySimulation.t(`hint_kvkk`);
            if (ds.covertFlag) return window.mySimulation.t(`hint_covert`);
            if (ds.exploit >= 45) return window.mySimulation.t(`hint_exploit`);
            if (ds.trust < this.TRUST_FLOOR && state.currentPeriod >= 2) return window.mySimulation.t(`hint_trust`);
            if (state.currentPeriod >= 3 && ds.contain < 40) return window.mySimulation.t(`hint_contain`);
            if (ds.trust >= this.TRUST_FLOOR && ds.contain >= this.CONTAIN_TARGET && ds.exploit <= 30) return window.mySimulation.t(`hint_strong`);
            return null;
        }

